WITH cleaned AS (SELECT id, order_id, carrier, shipped_date, delivered_date, LENGTH(status) AS status_length FROM shipments WHERE shipped_date >= DATE '2024-01-12') SELECT *, SUM(status_length) OVER (PARTITION BY order_id ORDER BY status_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_length, SUM(status_length) OVER (PARTITION BY order_id ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_length FROM cleaned
